[TestMethod]
public void CalculateShipping_ZeroWeight_Throws()
{
    var calc = new DiscountCalculator();
    Assert.ThrowsExactly<ArgumentOutOfRangeException>(
        () => calc.CalculateShipping(50m, 0, false));
}

[TestMethod]
public void CalculateShipping_Exactly250_NotFree()
{
    var calc = new DiscountCalculator();
    var cost = calc.CalculateShipping(250m, 2.0, false);
    Assert.AreEqual(6.00m, cost);
}

[TestMethod]
public void CalculateShipping_JustOver250_Free()
{
    var calc = new DiscountCalculator();
    Assert.AreEqual(0m, calc.CalculateShipping(250.01m, 5.0, true));
}

[TestMethod]
public void CalculateShipping_HeavyItem_AddsHeavyFee()
{
    var calc = new DiscountCalculator();
    // 10.01kg: base = 5.00 + 5.005 = 10.005 → +15 = 25.005
    var cost = calc.CalculateShipping(50m, 10.01, false);
    var baseCost = 5.00m + (decimal)(10.01 * 0.50);
    Assert.AreEqual(baseCost + 15.00m, cost);
}

[TestMethod]
public void CalculateShipping_Exactly10kg_NoHeavyFee()
{
    var calc = new DiscountCalculator();
    var cost = calc.CalculateShipping(50m, 10.0, false);
    Assert.AreEqual(5.00m + (decimal)(10.0 * 0.50), cost);
}

[TestMethod]
public void CalculateShipping_Express_Adds50PercentSurcharge()
{
    var calc = new DiscountCalculator();
    var normalCost = calc.CalculateShipping(50m, 2.0, false);
    var expressCost = calc.CalculateShipping(50m, 2.0, true);
    Assert.AreEqual(normalCost * 1.50m, expressCost);
}

// -- ApplyCoupon tests --

